// Composition catalog (docs/COMPOSITION.md, site Syntax view "Composition" folder). The one source: node tools/composition/build.mjs
// writes site/data/composition.json (syntax@1 sections with Craft + generated Strudel forms) and the catalog part of docs/COMPOSITION.md.
// Entry: id, title, def (definition), why (music / sound science), when, code (Craft form; the Strudel form is generated by
// tools/lowering, never written here), check (what to measure: engine/composer command, spectrogram, ledger), anti (anti-patterns),
// tags (taxonomy words, #120), needs (engine the Syntax view detects: core | hooks | lanes; atoms ride on hooks), tool (engine/composer subcommand when one measures it).
// Content is CC0-1.0 like the rest of glyphcore content. Example pitches are generic (C minor / G minor cells written for this doc), never from a track.

export const FAMILIES = [
  ['mot', 'Motif transformations', 'motif', 'One short cell, many statements: the listener tracks identity through change. Every transformation keeps one property (rhythm, contour, intervals) and changes another.'],
  ['int', 'Interplay', 'interplay', 'How two or more lines share time and register: who speaks, who answers, who holds.'],
  ['xt', 'Cross-textural development', 'cross-texture', 'The same idea travels between instruments, registers and domains (pitch to rhythm, synth to voice), so a long track stays one piece.'],
  ['fs', 'Foreshadowing', 'foreshadow', 'Plant early, pay later: partial statements before the hook, the full hook at the drop, a callback at the end.'],
  ['lay', 'Layering and density', 'layering', 'How many things sound at once, in which roles and frequency slots, and how a loop evolves on each repeat.'],
  ['ten', 'Tension and release', 'tension', 'The grammar of expectation: harmonic, rhythmic, spectral and dynamic tension, and where it lands.'],
  ['en', 'Energy curves', 'energy', 'The macro shape of a track: energy per section and the ramps inside a phrase.'],
  ['tr', 'Transitions and dovetails', 'transition', 'How one section hands over to the next (docs/CONVENTIONS.md section 6 holds the shipped dt. atoms).'],
  ['grv', 'Groove and feel', 'groove', 'Rhythm sequence archetypes and micro-timing: swing, push and pull, ghost notes, polymeter (docs/CONVENTIONS.md sections 4-5).'],
  ['har', 'Harmonic design', 'harmony', 'Chord loops, voice leading, pedals and harmonic rhythm.'],
  ['bor', 'Tone borrowing', 'borrowing', 'Borrow pitch material from a parallel mode or key, or timbre, envelope and groove from another layer or genre.'],
  ['dis', 'Discordance', 'discordance', 'Intentional clashes (minor seconds, tritones, clusters, beating unisons) placed where tension is the point, and resolved on purpose.'],
  ['asn', 'Assonance and consonance', 'assonance', 'Sound-similarity that binds layers: shared formants, harmonic series, colours, rhythm cells and envelopes.'],
  ['cmp', 'Complementing', 'complement', 'One layer fills the gaps of another: in frequency, time, stereo, length and dynamics.'],
  ['syn', 'Synergy', 'synergy', 'Pairs that only work together: the sum is a new sound, not two sounds.'],
  ['clu', 'Clustering', 'clustering', 'Tone clusters, rhythmic clusters, event bursts in time, and clustering as analysis (bars, motifs).'],
  ['snd', 'Sound-design layering', 'sound-design', 'One instrument from several layers: sub, body, bite, air; parallel and serial processing.'],
  ['vox', 'Vocal as instrument', 'vocal-instrument', 'Pitched syllables, vowels and formant pads; no lyrics are written or implied.'],
  ['arr', 'Arrangement maps', 'arrangement', 'Section maps per genre as gates and masks, so a track is one program with selections, not copies.'],
];

const E = [];
const add = (fam, id, title, o) => E.push({ fam, id, title, ...o });
const M = 'atom("m", { type: "mini", body: "0 2 4 3" })\n'; // the reference cell used across the motif family (scale degrees)

// ------------------------------------------------------------------ motif transformations
add('mot', 'MOT-01', 'Transposition', { def: 'The whole cell moved up or down by a fixed interval; intervals and rhythm are kept.',
  why: 'Interval and rhythm patterns are what memory encodes for a melody (contour plus interval), so the cell is recognised at a new pitch; a new register also changes brightness and the chord it sits on.',
  when: 'Second half of a 16-bar phrase, a lift into the last drop, answering phrases.',
  code: M + '$: n(atoms.m).scale("C4:minor").s("triangle").hook("hygiene-lead")\n$: n(atoms.m).add(n(4)).scale("C4:minor").s("triangle").hook("hygiene-lead").late(1)',
  check: 'composer ledger: relation "transposed" (or "octave") to the first statement, with the semitone offset.',
  anti: ['Transposing every repeat (the listener loses the home pitch)', 'Chromatic transposition that leaves the key by accident (check composer discord, out-of-key share)'], tags: ['motif', 'lead'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-02', 'Sequence', { def: 'A transposition repeated in steps in consecutive windows (a chain: up a step, up a step).',
  why: 'Predictable stepwise displacement creates momentum: the ear extrapolates the next step and the arrival on a stable degree releases it.',
  when: 'Builds, pre-drops, bridges; two or three links, then break the chain.',
  code: M + '$: n(atoms.m).add(n("<0 1 2 4>")).scale("C4:minor").s("sawtooth").hook("hygiene-lead").lpf(1800)',
  check: 'composer ledger: relation "sequence" (transposed repeat in the next window of the same layer).',
  anti: ['Sequences longer than 3-4 links (a predictable rosalia tires fast)', 'Sequencing every layer in parallel (all motion, no anchor)'], tags: ['motif', 'build'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-03', 'Inversion', { def: 'Each interval flips direction (up a third becomes down a third), tonally inside the scale.',
  why: 'Contour is the strongest melodic cue; flipping it keeps rhythm and interval sizes, so the cell is related yet heard as an answer.',
  when: 'Response phrases, second verse or second drop, counterlines against the original.',
  code: 'atom("m", { type: "mini", body: "0 2 4 3" })\natom("mInv", { type: "mini", body: "0 -2 -4 -3" })\n$: n(atoms.m).scale("C4:minor").s("triangle").hook("hygiene-lead")\n$: n(atoms.mInv).scale("C4:minor").s("triangle").hook("hygiene-lead").late(1)',
  check: 'composer ledger: relation "inverted".',
  anti: ['Inverting a cell whose identity is its rhythm only (no audible change)', 'Real (chromatic) inversion that leaves the key'], tags: ['motif'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-04', 'Retrograde and retro-inversion', { def: 'The pitches (and optionally the rhythm) played backwards; retro-inversion also flips intervals.',
  why: 'A weaker relation than transposition (memory is forward), so it reads as new material with a family resemblance; good for development sections that must not sound like the hook.',
  when: 'Breakdowns, B-sections, turnarounds.',
  code: M + '$: n(atoms.m).scale("C4:minor").s("sawtooth").hook("hygiene-pluck")\n$: n(atoms.m).rev().scale("C4:minor").s("sawtooth").hook("hygiene-pluck").late(1)',
  check: 'composer ledger: relation "retrograde" / "retro-inverted".',
  anti: ['Expecting listeners to recognise retrograde of a long line (only short cells survive)'], tags: ['motif'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-05', 'Augmentation and diminution', { def: 'Note values doubled (augmentation) or halved (diminution); pitches kept.',
  why: 'Time-scaling keeps contour and intervals; augmentation reads as weight and calm, diminution as urgency. In half-time genres augmentation turns a drop riff into a pad line.',
  when: 'Augment for intros, breakdowns and outro callbacks; diminish in builds and fills.',
  code: M + '$: n(atoms.m).scale("C4:minor").s("triangle").hook("hygiene-lead")\n$: n(atoms.m).slow(2).scale("C3:minor").s("supersaw").hook("hygiene-pad").gain(0.3)',
  check: 'composer ledger: relation "augmented" / "diminished" (IOIs x2 / x0.5).',
  anti: ['Diminution past the 1/16 grid at club tempos (smear)', 'Augmenting into sustained notes that mask the vocal band'], tags: ['motif', 'pad'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-06', 'Fragmentation', { def: 'A piece of the cell (usually its head or tail) repeated on its own.',
  why: 'The fragment is cheap to recognise and leaves room; repetition of a fragment builds expectation for the whole.',
  when: 'Teasers (FS-01), builds (shorter and shorter fragments), fills.',
  code: M + '$: n(atoms.m).linger("<1 0.5 0.25 0.25>").scale("C4:minor").s("triangle").hook("hygiene-lead")',
  check: 'composer ledger: relation "fragment" (a contiguous piece of >= 3 notes).',
  anti: ['Fragments of a cell that has not yet been established and will never come (no payoff)'], tags: ['motif', 'build'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-07', 'Extension', { def: 'The cell continues past its end with new notes (an answer tail), often to reach a cadence.',
  why: 'The head keeps identity, the tail adds direction; ending on a stable degree gives closure.',
  when: 'The 4th bar of a 4-bar phrase, phrase endings before section changes.',
  code: M + 'atom("tail", { type: "mini", body: "2 1 0 -1" })\n$: n(cat(atoms.m, atoms.m, atoms.m, atoms.tail)).scale("C4:minor").s("sawtooth").hook("hygiene-lead").lpf(2000)',
  check: 'composer ledger: relation "extension" or a motif "grown from" the first (grown_from).',
  anti: ['Tails that never resolve (no cadence anywhere in the track)'], tags: ['motif'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-08', 'Rhythmic displacement', { def: 'The same cell starting at a different point of the bar (an eighth or a beat later).',
  why: 'Metric position changes accent: the same notes against the grid make new syncopation (rhythmic dissonance) without new material.',
  when: 'Second half of a drop, switch-ups, tension before a downbeat.',
  code: M + '$: n(atoms.m).scale("C4:minor").s("triangle").hook("hygiene-lead")\n$: n(atoms.m).late(0.125).scale("C5:minor").s("triangle").hook("hygiene-pluck").gain(0.5)',
  check: 'composer ledger: relation "displaced" (same intervals and rhythm, shifted start); composer feel: syncopation index rises.',
  anti: ['Displacing the kick or the bass root (the floor loses the one)'], tags: ['motif', 'syncopated'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-09', 'Interval expansion and compression', { def: 'Same contour and rhythm, wider or narrower steps.',
  why: 'Contour identity holds while range changes energy: expansion opens (lift), compression tightens (tension, chromatic menace).',
  when: 'Expand in the last drop; compress in builds and dark breakdowns.',
  code: 'atom("m", { type: "mini", body: "0 2 4 3" })\natom("mWide", { type: "mini", body: "0 4 7 5" })\n$: n("<0 1>").pick([atoms.m, atoms.mWide]).scale("C4:minor").s("sawtooth").hook("hygiene-lead")',
  check: 'composer ledger: relation "expanded" / "compressed" (same contour, larger / smaller interval sum).',
  anti: ['Expansion past an octave in a lead that must sit in the vocal band'], tags: ['motif'], tool: 'ledger', needs: 'hooks' });
add('mot', 'MOT-10', 'Reharmonization', { def: 'The melody kept, the chords under it changed (relative minor, borrowed chord, new bass note).',
  why: 'The same melody note gets a new function (root, third, ninth): its colour and stability change while the tune is recognised.',
  when: 'Last chorus or drop, breakdowns (sentimental lift), outros.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("triangle").hook("hygiene-lead")\n$: chord("<Cm Cm Ab Ab Fm Fm G G>/2").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord: chord roots per bar change while composer ledger keeps the melody "exact".',
  anti: ['Reharmonising under a vocal hook without checking clashes (minor 2nds against held melody notes)'], tags: ['harmony', 'keys'], tool: 'discord', needs: 'hooks' });
add('mot', 'MOT-11', 'Ornament', { def: 'Extra notes around the cell: grace notes, turns, trills, ghosted repeats; the cell notes stay on their steps.',
  why: 'Adds detail on repeats without changing identity; the ear hears the frame plus decoration.',
  when: 'Embellishment ladder (LAY-05): the 3rd and 4th repeat of a loop.',
  code: M + '$: n(atoms.m).off(1/16, x => x.add(n(1)).gain(0.4)).scale("C4:minor").s("triangle").hook("hygiene-pluck")',
  check: 'composer ledger: relation "ornamented".',
  anti: ['Ornaments on every note (the frame disappears)', 'Grace notes on the bass at low frequencies (mud)'], tags: ['motif', 'accents'], tool: 'ledger', needs: 'hooks' });

// ------------------------------------------------------------------ interplay
add('int', 'INT-01', 'Call and response', { def: 'One phrase asks, another answers, in alternating time slots.',
  why: 'Turn-taking keeps each voice audible (no masking in time) and sets up a predictable cycle that can then be broken.',
  when: 'Riddim and dubstep bass phrases (A/B basses), lead vs vocal chop, hook sections.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask("<1 0>")\n$: n("4 3 1 0").scale("C5:minor").s("triangle").hook("hygiene-pluck").mask("<0 1>")',
  check: 'composer layers: high onset_complement between the two lanes and composer ledger shows the answer as a related motif (inverted, transposed).',
  anti: ['Answer louder or busier than the call every time (no hierarchy)', 'Both voices in the same band (they still mask across the seam)'], tags: ['call-response', 'lead'], tool: 'layers', needs: 'hooks' });
add('int', 'INT-02', 'Counterline', { def: 'A second melody that moves against the first: contrary or oblique motion, notes in the first line\'s rests.',
  why: 'Independent contour (contrary motion) is heard as a separate stream (auditory stream segregation); filling rests adds detail without masking.',
  when: 'Second half of drops, relief sections, last chorus.',
  code: '$: n("0 ~ 2 ~ 4 ~ 3 ~").scale("C4:minor").s("sawtooth").hook("hygiene-lead")\n$: n("~ 7 ~ 6 ~ 5 ~ 4").scale("C4:minor").s("triangle").hook("hygiene-pluck").gain(0.5)',
  check: 'engine/motifs counterlines (contrary/oblique share); composer layers onset_complement > 0.7.',
  anti: ['Parallel fifths/octaves for long stretches (fuses into one stream)', 'A counterline in the same register as the vocal'], tags: ['lead', 'counterline'], tool: 'layers', needs: 'hooks' });
add('int', 'INT-03', 'Hocket', { def: 'One line split note by note between two voices or timbres.',
  why: 'The ear fuses the line (pitch proximity) while the timbre alternation adds motion and stereo interest.',
  when: 'Plucks and bells in breakdowns; stereo ping-pong leads.',
  code: '$: n("0 2 4 3 2 4 5 4").scale("C4:minor").s("triangle").hook("hygiene-pluck").struct("x ~ x ~ x ~ x ~").pan(0.2)\n$: n("0 2 4 3 2 4 5 4").scale("C4:minor").s("square").hook("hygiene-pluck").struct("~ x ~ x ~ x ~ x").pan(0.8).gain(0.4)',
  check: 'composer layers: onset_complement close to 1 and rhythm_rhyme close to 0 for the pair; pan_contrast > 0.4.',
  anti: ['Hocketing across very different registers (the line breaks into two streams)'], tags: ['stereo', 'pluck'], tool: 'layers', needs: 'hooks' });
add('int', 'INT-04', 'Handoff (relay)', { def: 'The motif passes from one instrument to another at a section or phrase boundary.',
  why: 'Continuity of material with a change of colour: the listener follows the motif, so the arrangement can change around it.',
  when: 'Section changes (lead to pluck at the breakdown, pluck to vocal at the hook).',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask("<1 1 0 0>")\n$: n("0 2 4 3").scale("C5:minor").s("triangle").hook("hygiene-pluck").mask("<0 0 1 1>")',
  check: 'composer ledger: the motif lists both layers in migration order with no gap bar between them.',
  anti: ['Handoff with an empty bar in between (the thread drops)'], tags: ['transition', 'lead'], tool: 'ledger', needs: 'hooks' });
add('int', 'INT-05', 'Unison and octave doubling', { def: 'Two timbres play the same line at the same pitch or octaves apart.',
  why: 'Partials of both sounds fuse into one richer timbre (common fate); the octave adds brightness without a new line.',
  when: 'Drops (lead + supersaw octave), bass + sub doubling, emphasis on a hook bar.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").superimpose(x => x.add(n(7)).s("square").gain(0.3))',
  check: 'composer layers (stems): synergy lufs_gain_db > 0 (coherent), assonance mfcc_cosine high; composer ledger relation "octave".',
  anti: ['Doubling with slight detune at low pitch (beating in the sub, see DIS-03)', 'Doubling everything (density with no new information)'], tags: ['lead', 'layering'], tool: 'layers', needs: 'hooks' });
add('int', 'INT-06', 'Imitation and canon', { def: 'A second voice repeats the first after a delay, at the same or another pitch.',
  why: 'The echo creates a predictable texture of overlapping copies (delay lines are acoustic canons); at a fifth it implies harmony.',
  when: 'Arps, plucks, ambient intros; DnB and progressive layers.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("triangle").hook("hygiene-pluck").off(1/4, x => x.add(n(4)).gain(0.5))',
  check: 'composer ledger: the same motif in two layers (or one) with "transposed" / "displaced" relations a fixed delay apart.',
  anti: ['Canon at a tempo-unrelated delay (smear)', 'Imitation in the low end'], tags: ['delay-echo', 'pluck'], tool: 'ledger', needs: 'hooks' });
add('int', 'INT-07', 'Pedal and ostinato under melody', { def: 'A held or repeated bass note (pedal) or riff (ostinato) while the melody and chords move.',
  why: 'A fixed reference makes harmonic motion above it audible as tension (non-chord tones against the pedal) and gives trance-like continuity.',
  when: 'Intros, builds (dominant pedal), phonk and techno grooves.',
  code: '$: note("g1*8").s("sawtooth").hook("hygiene-bass").lpf(400)\n$: n("<0 2 4 3>*2").scale("G3:minor").s("triangle").hook("hygiene-keys")',
  check: 'composer discord: roughness rises when upper chords leave the pedal and falls on return; engine/motifs chord loop over one bass root.',
  anti: ['A pedal under a chord that clashes for many bars without resolution (check unresolved clashes)'], tags: ['bass', 'drone'], tool: 'discord', needs: 'hooks' });

// ------------------------------------------------------------------ cross-textural development
add('xt', 'XT-01', 'Motif migration', { def: 'The motif is stated by different layers over the track: bass, then lead, pluck, vocal syllable, pad, percussion rhythm.',
  why: 'One idea in many colours gives unity with variety; each new texture is a new event even though no new material is added.',
  when: 'Long tracks (3+ minutes), extended mixes, any track whose sections risk sounding unrelated.',
  code: 'atom("m", { type: "mini", body: "0 2 4 3" })\natom("one", { type: "mini", body: "<1 0 0 0>" })\natom("two", { type: "mini", body: "<0 1 0 0>" })\natom("three", { type: "mini", body: "<0 0 1 0>" })\n$: n(atoms.m).scale("C2:minor").s("sawtooth").hook("hygiene-bass").mask(atoms.one)\n$: n(atoms.m).scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask(atoms.two)\n$: n(atoms.m).scale("C5:minor").s("triangle").hook("hygiene-pluck").mask(atoms.three)',
  check: 'composer ledger: one motif with 3+ layers in its migration list.',
  anti: ['Migration with a different motif in each layer (no thread)', 'Every layer stating the motif at once (no migration, only doubling)'], tags: ['motif', 'cross-texture'], tool: 'ledger', needs: 'hooks' });
add('xt', 'XT-02', 'Timbral morphing', { def: 'The same notes, with the timbre changing over time (filter, vowel, waveform, FM index).',
  why: 'Timbre is a separate perceptual dimension: a slow change of spectral centroid reads as development and energy without new pitches.',
  when: 'Long loops (techno, riddim), builds, breakdowns.',
  code: '$: n("0 2 4 3").scale("C3:minor").s("sawtooth").hook("hygiene-bass").lpf(sine.slow(8).range(300, 3000)).vowel("<a e i o>")',
  check: 'composer scan: the band map and per-bar band energy shift bar to bar (energy moving between bands; scan reports no single centroid number) while composer ledger reports "exact" statements.',
  anti: ['Morphing that ends where it began with no arrival', 'Morphing several layers in sync (one wash)'], tags: ['filter-sweep', 'formant'], tool: 'scan', needs: 'hooks' });
add('xt', 'XT-03', 'Rhythm from pitch', { def: 'The motif\'s rhythm alone, played on an unpitched layer (rim, hat, noise).',
  why: 'Rhythm is a strong identity cue; the percussion echo keeps the motif present while the melody rests, and builds anticipation.',
  when: 'Builds and intros before the hook (FS-01), breakdowns.',
  code: 'atom("mr", { type: "mini", body: "x ~ x x ~ x ~ ~" })\n$: n("0 ~ 2 4 ~ 3 ~ ~").scale("C4:minor").s("triangle").hook("hygiene-lead").mask("<0 1>")\n$: s("white").struct(atoms.mr).decay(0.04).hpf(4000).gain(0.4).mask("<1 0>")',
  check: 'composer ledger: rhythm_echoes lists the motif and the unpitched layer.',
  anti: ['A rhythm echo that is an even grid (carries no identity)'], tags: ['cross-texture', 'drums'], tool: 'ledger', needs: 'hooks' });
add('xt', 'XT-04', 'Pitch from rhythm', { def: 'A drum or percussion rhythm becomes a melodic line (the hat accents become pluck notes).',
  why: 'Binding melody to the groove makes them lock (shared onsets); the melody feels inevitable.',
  when: 'Drops, especially percussion-led genres (electro, hyphy, riddim).',
  code: 'atom("hatAcc", { type: "mini", body: "x ~ ~ x ~ ~ x ~" })\n$: s("white").struct(atoms.hatAcc).decay(0.03).hpf(6000).gain(0.4)\n$: n("0 3 5").scale("C4:minor").struct(atoms.hatAcc).s("triangle").hook("hygiene-pluck")',
  check: 'composer layers: rhythm_rhyme close to 1 between the drum lane and the melodic lane.',
  anti: ['Copying a dense hat pattern into a melody (too many notes)'], tags: ['cross-texture', 'pluck'], tool: 'layers', needs: 'hooks' });
add('xt', 'XT-05', 'Motif as vocal syllable', { def: 'The motif sung on vowels or syllables (no words), or a synthetic vowel playing its pitches.',
  why: 'Voice-like formants grab attention (speech sensitivity) and make a synth motif feel human at the hook.',
  when: 'Hooks and drops of melodic genres; phonk vocal chops; breakdowns.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").vowel("<a o>").hook("hygiene-vox").lpf(3000)',
  check: 'composer layers: shared vowel with another layer (ASN-01); composer ledger: motif in the vox lane.',
  anti: ['Writing lyrics into the user\'s track (never infer words)', 'Vowel filters on a sub-bass fundamental (formants sit above 300 Hz)'], tags: ['vox', 'formant'], tool: 'ledger', needs: 'hooks' });

// ------------------------------------------------------------------ foreshadowing
add('fs', 'FS-01', 'Pre-echo teaser', { def: 'A fragment or the rhythm of the drop hook in the intro or build.',
  why: 'Exposure creates familiarity; the full statement later is then recognised and rewarding (mere exposure, expectation).',
  when: 'Intro bar 5-8, build bars 1-4.',
  code: 'atom("hook", { type: "mini", body: "0 2 4 3 2 ~ 0 ~" })\n$: n(atoms.hook).linger(0.25).scale("C4:minor").s("triangle").hook("hygiene-pluck").lpf(800).mask("<1 1 0 0>")\n$: n(atoms.hook).scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask("<0 0 1 1>")',
  check: 'composer foreshadow: pre_echo PASS (fragment, filtered or rhythm echo before the first drop).',
  anti: ['The full hook at full level in the intro (payoff given away, see FS-04)'], tags: ['foreshadow', 'intro-reveal'], tool: 'foreshadow', needs: 'hooks' });
add('fs', 'FS-02', 'Filtered, reversed or sparse preview', { def: 'The hook itself, low-passed, reversed or thinned (degraded), before the drop.',
  why: 'Removing brightness or notes keeps identity at lower salience: the listener half-hears it, and the drop "opens" it.',
  when: 'Builds (opening filter), the bar before the drop (reversed), intros.',
  code: '$: n("0 2 4 3 2 ~ 0 ~").scale("C4:minor").s("sawtooth").hook("hygiene-lead").lpf(sine.slow(4).range(300, 900)).degradeBy(0.4).mask("<1 0>")\n$: n("0 2 4 3 2 ~ 0 ~").rev().scale("C4:minor").s("sawtooth").hook("hygiene-lead").hpf(1200).gain(0.3).mask("<0 1>")',
  check: 'composer foreshadow: teasers marked "filtered" (lpf < 2 kHz or level < 0.6 x drop); composer scan band map: highs absent before the drop.',
  anti: ['A filter so closed the teaser is inaudible (no exposure)'], tags: ['foreshadow', 'filter-sweep'], tool: 'foreshadow', needs: 'hooks' });
add('fs', 'FS-03', 'Planted harmony', { def: 'The drop\'s chord loop sounds early (pad, bass pedal) before the hook melody arrives.',
  why: 'The harmonic frame primes the key and the melody\'s target notes; the hook then lands on expected ground.',
  when: 'Intros and breakdowns that lead into a drop.',
  code: '$: chord("<Cm Ab Eb Bb>").voicing().s("supersaw").hook("hygiene-pad").lpf(700).gain(0.25)\n$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask("<0!4 1!4>")',
  check: 'composer foreshadow: planted_harmony PASS (drop pitch-class sets found before the first drop).',
  anti: ['New chords only at the drop (the hook arrives on unknown ground)'], tags: ['foreshadow', 'harmony'], tool: 'foreshadow', needs: 'hooks' });
add('fs', 'FS-04', 'Delayed payoff', { def: 'The full, bright, same-layer statement of the hook is withheld until the drop (or a later drop).',
  why: 'Anticipation is the source of the reward response; withholding the expected event raises its value when it lands.',
  when: 'Every drop-based form; second drops can withhold one more layer.',
  code: 'atom("pay", { type: "gate", body: "@3b" })\nhooks.bind("open", [["lpf", 6000]], atoms.pay)\nhooks.bind("open", [["lpf", 600]], "<3b")\n$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").use("open")',
  check: 'composer foreshadow: withheld PASS (no full unfiltered same-layer statement before the first drop).',
  anti: ['Withholding so long the hook never fully arrives', 'Revealing it in bar 1 of the intro'], tags: ['foreshadow', 'build-drop', 'gate'], tool: 'foreshadow', needs: 'hooks' });
add('fs', 'FS-05', 'Callback and outro return', { def: 'The hook (or its seed) returns after the last drop: augmented, filtered or on another layer.',
  why: 'Return closes the form (rounded binary logic); the listener leaves with the hook in memory.',
  when: 'Outro, last 4-8 bars.',
  code: '$: n("0 2 4 3").slow(2).scale("C4:minor").s("supersaw").hook("hygiene-pad").lpf(1200).gain(0.3)',
  check: 'composer foreshadow: callback PASS (a statement after the last drop or in the last section).',
  anti: ['An outro of new material that never returns to the hook'], tags: ['foreshadow', 'fade-out'], tool: 'foreshadow', needs: 'hooks' });
add('fs', 'FS-06', 'Return after contrast', { def: 'After a contrasting section (breakdown, bridge) the motif returns, often varied (MOT family).',
  why: 'Contrast resets habituation, so the return feels fresh; variation on return signals progress.',
  when: 'Second drop, last chorus.',
  code: '$: n("<[0 2 4 3] [~] [0 2 4 3] [0 4 7 5]>").scale("C4:minor").s("sawtooth").hook("hygiene-lead")',
  check: 'composer ledger: the motif is not flagged "never returns"; a gap of >= 4 bars precedes a later statement.',
  anti: ['Motifs stated in one section only (ledger flag "never returns")'], tags: ['motif', 'form'], tool: 'ledger', needs: 'hooks' });

// ------------------------------------------------------------------ layering and density
add('lay', 'LAY-01', 'Detail budget per section', { def: 'Plan how many events and layers each section may have, from the energy curve (EN-01).',
  why: 'Attention is limited: the ear follows 2-3 streams in focus; detail beyond that becomes texture. A budget keeps the peak sections peaky.',
  when: 'Before building: write the budget into the brief, check after each render.',
  code: 'atom("intro", { type: "mini", body: "<1 1 0 0 0 0>" })\natom("drop", { type: "mini", body: "<0 0 1 1 1 1>" })\n$: s("bd*4").hook("hygiene-kick").mask(atoms.drop)\n$: s("hh*8").hook("hygiene-hat").gain(0.4)\n$: note("c2*8").s("sawtooth").hook("hygiene-bass").mask(atoms.drop)\n$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").gain(0.2).mask(atoms.intro)',
  check: 'composer density: mean layers per section inside the role target; suggestions "add" / "remove".',
  anti: ['Every section at the same density (flat energy curve)', 'The intro already at drop density'], tags: ['layering', 'form'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-02', 'Layer ladder: core, support, ornament, atmos', { def: 'Each layer gets a role: core (beat, bass, hook), support (chords, counterline), ornament (fills, one-shots), atmos (pads, noise, reverb beds).',
  why: 'Roles make subtraction decisions easy (remove ornaments first, never the core) and keep the hierarchy readable.',
  when: 'Every arrangement; label lanes with tags so selections follow roles.',
  code: 'kick: s("bd*4").hook("hygiene-kick").tags("core")\nbass: note("c2*8").s("sawtooth").hook("hygiene-bass").tags("core")\nkeys: chord("<Cm Ab>").voicing().s("triangle").hook("hygiene-keys").tags("support")\nfill: s("~ ~ ~ sd*4").hook("hygiene-snare").tags("ornament").mask("<0 0 0 1>")\nair: s("pink").hpf(6000).gain(0.05).tags("atmos")\ntagged("ornament | atmos").mute("<2b")',
  check: 'composer density: the "roles" map (core, support, ornament, atmos per layer) and the per-bar role counts.',
  anti: ['Two core leads fighting for attention', 'No atmos layer anywhere (dry, small)'], tags: ['layering', 'tag'], tool: 'density', needs: 'lanes' });
add('lay', 'LAY-03', 'Simultaneous layer counts per genre and section', { def: 'Target ranges of simultaneous lanes (each drum piece counts) per section role, scaled per genre.',
  why: 'Producer-reported norms (COMPOSITION_RESEARCH.md): drops are the fullest section, cloud and riddim stay sparse, big-room and DnB carry more. Design call: intro 2-6, verse 4-9, build 5-10, drop 8-14, breakdown 3-7, outro 2-6 lanes; genre factor cloud 0.6, riddim 0.75, trap 0.85, phonk 0.9, house / dubstep / DnB 1.0, big room 1.1; rock 0.8, metal 0.85, industrial 0.85 (design calls, #159: a band arrangement is 5-8 lanes; the licensed DAW study has n < 3 per genre, docs/FORM_PROFILES.md).',
  when: 'Planning and checking; override the factor with --genre.',
  code: '// the targets live in engine/composer/density.py (TARGETS, GENRE); a sparse riddim drop:\n$: s("bd ~ ~ ~ ~ ~ ~ ~, ~ ~ ~ ~ sd ~ ~ ~").hook("hygiene-kick")\n$: s("hh*8").hook("hygiene-hat").gain(0.3)\n$: note("c1 ~ ~ c1 ~ ~ c1 ~").s("sine").hook("hygiene-sub")\n$: note("c2 ~ ~ c2 ~ ~ c2 ~").s("sawtooth").hook("hygiene-growl").lpf(sine.fast(2).range(300, 1500))',
  check: 'composer density --genre G: section means against the scaled targets.',
  anti: ['Treating the numbers as rules (they are conventions; the brief wins)'], tags: ['layering'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-04', 'Frequency-slot allocation', { def: 'Each layer owns a band (sub, bass, low-mid, mid, high-mid, presence, air); at most one owner in sub and two in bass.',
  why: 'Simultaneous masking is strongest within a critical band: two sounds in one slot blur; in different slots both stay clear.',
  when: 'Sound selection and octave choice before EQ; carve with hpf/lpf after.',
  code: '$: note("c1*4").s("sine").hook("hygiene-sub")\n$: note("c3 eb3 g3 bb3").s("sawtooth").hook("hygiene-keys").hpf(250)\n$: note("c5 g5").s("triangle").hook("hygiene-pluck").hpf(1200)\n$: s("hh*8").hook("hygiene-hat")',
  check: 'composer density: "slot" suggestions (sub shared by > 1, bass by > 2 layers); composer layers masking_risk; composer scan band map.',
  anti: ['Two layers in the sub band without ducking (SYN-01)', 'Every layer full range (no slot left)'], tags: ['mix', 'low-end'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-05', 'Embellishment ladder per repeat', { def: 'Each repeat of a loop adds or changes one small thing: repeat 1 plain, 2 + ornament, 3 + counter-rhythm, 4 + fill.',
  why: 'Exact repetition habituates within 2-4 cycles; one change per repeat keeps attention while the loop identity stays.',
  when: 'Every 8-16 bar loop in drops and verses.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("triangle").hook("hygiene-pluck").sometimesBy("<0 0 0.3 0.6>", x => x.ply(2))\n$: s("hh*8").hook("hygiene-hat").gain(0.4).lastOf(4, x => x.fast(2))',
  check: 'composer density: no "embellish" suggestion (same active set for >= 8 bars).',
  anti: ['Random variation (probability with no plan)', 'Changing the hook itself on every repeat'], tags: ['accents', 'probability'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-06', 'Ear-candy cadence', { def: 'Small one-shots (reverse cymbal, vocal chop, delay throw, riser) placed at phrase marks: every 4, 8 or 16 bars.',
  why: 'Phrase boundaries are where attention resets; a marker there confirms the grid and rewards listening (producer-reported: once per 8 bars).',
  when: 'Drops and verses; fewer in intros (DJ mixing room).',
  code: '$: s("white").attack(0.4).decay(0.05).sustain(0).hpf(3000).gain(0.25).struct("<~ ~ ~ [~ ~ ~ x]>")\n$: s("bd*4").hook("hygiene-kick")',
  check: 'composer density: ornament-role layers have onsets every 4-8 bars; no "embellish" suggestion.',
  anti: ['Ear candy on every bar (it becomes texture)', 'Candy that masks the vocal'], tags: ['fx', 'transition'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-07', 'Detail by register', { def: 'Busy parts high, slow parts low: the bass moves least, the top moves most.',
  why: 'Low frequencies need longer to be resolved (fewer cycles per note) and mask more; fast detail is clear only in the highs.',
  when: 'Writing parts: check note rates per band.',
  code: '$: note("c1 ~ ~ ~ c1 ~ ~ ~").s("sine").hook("hygiene-sub")\n$: note("c3 ~ eb3 ~").s("sawtooth").hook("hygiene-keys")\n$: note("c5 eb5 g5 bb5 c6 bb5 g5 eb5").s("triangle").hook("hygiene-arp").gain(0.3)',
  check: 'composer density + ledger: onset rate per band (sub and bass lanes lowest).',
  anti: ['Fast 1/16 basslines with long release (smear)'], tags: ['layering', 'low-end'], tool: 'density', needs: 'hooks' });
add('lay', 'LAY-08', 'Contrast by subtraction', { def: 'Energy by removing layers before an arrival: a drop-out bar, a beat of silence, the kick gone for the last bar of the build.',
  why: 'Loudness and density are judged relative to what came before (adaptation); a gap makes the return feel larger than adding more would.',
  when: 'The bar or beat before each drop; inside drops every 8-16 bars.',
  code: 'atom("gap", { type: "mini", body: "<1 1 1 [1 1 1 0]>" })\n$: s("bd*4").hook("hygiene-kick").mask(atoms.gap)\n$: note("c2*8").s("sawtooth").hook("hygiene-bass").mask(atoms.gap)',
  check: 'composer density: no "subtract" suggestion before drops; the curve dips in the bar before a drop.',
  anti: ['Subtracting the hook (subtract support and ornaments first)'], tags: ['build-drop', 'sparse'], tool: 'density', needs: 'hooks' });

// ------------------------------------------------------------------ tension and release
add('ten', 'TEN-01', 'Harmonic tension', { def: 'Dominant function, leading tones, suspensions and non-chord tones that want to move.',
  why: 'Tonal expectation: unstable degrees (7, 4, b2) predict motion to stable ones (1, 3, 5); delaying it holds tension.',
  when: 'Pre-drop bars (V or bVII), turnarounds.',
  code: '$: chord("<Cm Ab Fm G7>").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)\n$: n("<[0 2 4 3] [2 4 5 4] [3 5 7 5] [6 5 4 6]>").scale("C4:harmonic minor").s("sawtooth").hook("hygiene-lead")',
  check: 'composer discord: the leading tone (raised 7) named in the pre-drop section; roughness peak resolved on the drop downbeat.',
  anti: ['A dominant that never resolves anywhere in the track'], tags: ['tension', 'harmony'], tool: 'discord', needs: 'hooks' });
add('ten', 'TEN-02', 'Rhythmic tension', { def: 'Subdivision acceleration: snare 1/4 -> 1/8 -> 1/16 -> 1/32 rolls, hats doubling, ratchets.',
  why: 'Increasing event rate raises arousal and predicts an endpoint (the downbeat).',
  when: 'The last 2-8 bars of a build.',
  code: '$: s("sd").hook("hygiene-snare").fast("<4 8 16 [32 0]>").velocity(saw.range(0.4, 1).slow(4))',
  check: 'composer density: onsets per bar rising through the build; composer cluster: build bars in their own cluster.',
  anti: ['Rolls that run into the drop downbeat (the gap is lost)'], tags: ['build-drop', 'crescendo'], tool: 'density', needs: 'hooks' });
add('ten', 'TEN-03', 'Spectral tension', { def: 'Brightness rises before the arrival: high-pass rising on the mix, low-pass opening on leads, noise risers.',
  why: 'Spectral centroid correlates with perceived tension and energy; removing lows (HPF) makes the return of the low end the release.',
  when: 'Builds; the whole mix or the music bus, not the kick alone.',
  code: '$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").hpf(saw.range(200, 2000).slow(4)).gain(0.25)\n$: s("white").hook("hygiene-riser").attack(6).release(0.1).lpf(saw.range(500, 9000).slow(4)).gain(0.2).slow(4)',
  check: 'composer scan: band map shows sub and bass falling, presence rising across the build (the brightening is read from the band shift; scan reports no centroid number).',
  anti: ['Masking production moves because they sound "EDM": risers and filter builds are tools in any genre (user directive)'], tags: ['filter-sweep', 'riser'], tool: 'scan', needs: 'hooks' });
add('ten', 'TEN-04', 'Dynamic tension: the gap', { def: 'Silence or near-silence (a beat or a bar) immediately before the drop.',
  why: 'A gap resets loudness adaptation and creates maximal temporal expectation of the downbeat.',
  when: 'Before drops; before a beat switch.',
  code: 'atom("lastBeat", { type: "mini", body: "<1 1 1 [1 1 1 0]>" })\n$: s("bd*4, hh*8").hook("hygiene-kick").mask(atoms.lastBeat)',
  check: 'composer density: the last bar before a drop has fewer layers (no "subtract" suggestion).',
  anti: ['A gap with a reverb tail filling it completely'], tags: ['build-drop', 'sparse'], tool: 'density', needs: 'hooks' });
add('ten', 'TEN-05', 'Release grammar', { def: 'What happens on the arrival downbeat: impact, sub returns, hook enters, filter fully open, crash.',
  why: 'Several cues landing together (cross-modal: low end, brightness, loudness, hook) make the arrival unambiguous.',
  when: 'Drop downbeats; chorus downbeats.',
  code: '$: s("bd*4").hook("hygiene-kick").mask("<0 1>")\n$: note("c1").s("sine").hook("hygiene-impact").decay(1.5).struct("<~ x>")\n$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").mask("<0 1>")',
  check: 'composer cluster: the drop starts a new cluster on its first bar; composer density: the curve jumps at the drop bar.',
  anti: ['Staggered entries after the downbeat that blur the arrival (unless intended: then make it a pattern)'], tags: ['build-drop'], tool: 'cluster', needs: 'hooks' });

// ------------------------------------------------------------------ energy
add('en', 'EN-01', 'Macro energy arc', { def: 'An energy level 1-10 per section written before building: e.g. intro 3, build 5, drop 9, break 4, build 6, drop 10, outro 3.',
  why: 'Contrast between sections drives interest; the second peak higher than the first rewards staying.',
  when: 'The brief; the density budget derives from it (LAY-01).',
  code: 'atom("energy", { type: "mini", body: "<0.3 0.5 0.9 0.4 0.6 1 0.3>" })\n$: s("bd*4, hh*8").hook("hygiene-kick").gain(atoms.energy)',
  check: 'composer density curve and composer scan band map follow the planned arc; the last drop >= the first.',
  anti: ['A flat arc (every section at 8)', 'The highest point in the first 30 seconds'], tags: ['form', 'dynamics'], tool: 'density', needs: 'hooks' });
add('en', 'EN-02', 'Phrase ramp', { def: 'Inside a 8 or 16-bar section, energy rises toward the phrase end (fills, opening filter, added hats).',
  why: 'Phrase-level expectation: the end of a hypermetric unit is where change is expected.',
  when: 'Every section that leads into another.',
  code: '$: s("hh*8").hook("hygiene-hat").gain(saw.range(0.2, 0.6).slow(8))\n$: s("~ sd").hook("hygiene-snare").lastOf(8, x => x.ply(4))',
  check: 'composer density: within-section layer count or onset count rises to the last bar.',
  anti: ['Every phrase ending with the same fill (habituates)'], tags: ['crescendo'], tool: 'density', needs: 'hooks' });
add('en', 'EN-03', 'False drop', { def: 'The build leads to an expected drop, but a different, sparser section (or a second build) arrives instead.',
  why: 'Violated expectation is surprising and makes the real drop that follows stronger.',
  when: 'Second build; once per track at most.',
  code: '$: s("bd*4").hook("hygiene-kick").mask("<1 0 1 1>")\n$: note("c2*8").s("sawtooth").hook("hygiene-bass").mask("<0 0 1 1>")',
  check: 'composer cluster: the bar after the build belongs to a breakdown-like cluster, the following one to the drop cluster.',
  anti: ['False drops twice in one track'], tags: ['build-drop', 'form'], tool: 'cluster', needs: 'hooks' });

// ------------------------------------------------------------------ transitions
add('tr', 'TR-01', 'Pickup fill', { def: 'A short fill in the last beat(s) before the new section (snare, toms, 808 slide).',
  why: 'Anacrusis: the upbeat points at the downbeat and connects the sections.',
  when: 'Every section change; vary the fill per occurrence.',
  code: '$: s("bd*4").hook("hygiene-kick")\n$: s("<~ ~ ~ [~ ~ ~ [sd sd sd sd]]>").hook("hygiene-snare")',
  check: 'composer density: an ornament-role onset in the last beat of each section.',
  anti: ['The same fill before every section'], tags: ['dovetail', 'transition'], tool: 'density', needs: 'hooks' });
add('tr', 'TR-02', 'Riser and impact', { def: 'A riser that ends exactly on the downbeat, an impact that starts on it (dt.rise / dt.hit).',
  why: 'Continuous pitch / noise rise predicts an endpoint; the impact confirms it.',
  when: 'Builds into drops, section changes in cinematic and EDM forms (and any genre that wants them).',
  code: 'atoms.import("pack:glyphcore/edm:atoms-edm-core")\n$: s("white").hook("hygiene-riser").attack(3.5).release(0.05).lpf(saw.range(400, 8000).slow(2)).gain(0.2).struct("<x ~>").slow(2)\n$: note("c1").s("sine").hook("hygiene-impact").decay(1.2).struct("<~ ~ x ~>")',
  check: 'composer scan: presence band rising over the build bars, then every band energy jumping together on the drop bar (read from per-bar band energy, not from onset times).',
  anti: ['A riser that stops before the downbeat (dead air) or overruns it'], tags: ['riser', 'transition'], tool: 'scan', needs: 'hooks' });
add('tr', 'TR-03', 'Drop-out bar', { def: 'All or most layers stop for the bar or beat before the new section (see TEN-04).',
  why: 'Contrast by subtraction at the seam.',
  when: 'Before drops and beat switches.',
  code: '$: s("bd*4, hh*8").hook("hygiene-kick").mask("<1 1 1 0>")',
  check: 'composer density: dip in the last bar of the section.',
  anti: ['Drop-outs before every section'], tags: ['transition', 'sparse'], tool: 'density', needs: 'hooks' });
add('tr', 'TR-04', 'Reverse swell', { def: 'A reversed tail (reverse cymbal, reversed chord) ending on the downbeat.',
  why: 'An amplitude envelope rising into the downbeat is an inverted decay: it reads as anticipation.',
  when: 'Into drops and choruses; into a vocal entry.',
  code: '$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-reverse").attack(1.8).release(0.02).gain(0.25).struct("<~ x>")',
  check: 'composer scan: energy rising through the last bar, ending at the downbeat.',
  anti: ['A swell that ends after the downbeat'], tags: ['transition', 'riser'], tool: 'scan', needs: 'hooks' });
add('tr', 'TR-05', 'Overlap tail and crossfade', { def: 'A layer of the old section rings into the new one, or two layers cross-fade over a bar.',
  why: 'Continuity across the seam: the ear follows the overlapping element through the change.',
  when: 'Breakdowns into drops (pad tail), section changes in house and DnB.',
  code: '$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").release(3).gain("<0.3 0.15>")\n$: note("c2*8").s("sawtooth").hook("hygiene-bass").gain("<0 0.5>")',
  check: 'composer density: the old layer active in the first bar of the new section.',
  anti: ['Long tails in the low band across a drop (mud on the downbeat)'], tags: ['transition', 'crossfade'], tool: 'density', needs: 'hooks' });
add('tr', 'TR-06', 'Delay throw', { def: 'One word or note sent to a long delay at a phrase end; the echoes bridge the gap.',
  why: 'Echoes keep the last event alive across silence, connecting phrases.',
  when: 'Phrase ends, before drops, vocal tags.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("triangle").hook("hygiene-pluck").delay("<0 0 0 0.6>").delaytime(0.375).delayfeedback(0.55)',
  check: 'composer scan: energy continuing in the mid band through the gap bar.',
  anti: ['Throws on every phrase'], tags: ['delay-echo', 'transition'], tool: 'scan', needs: 'hooks' });
add('tr', 'TR-07', 'Turnaround', { def: 'The last bar of a loop changes chord or riff so the loop "turns" back to the start.',
  why: 'Harmonic rhythm acceleration at the cycle end marks the boundary and drives back to bar 1.',
  when: '4 and 8-bar loops; hip-hop and house.',
  code: '$: chord("<Cm Cm Cm [Ab G]>").voicing().s("triangle").hook("hygiene-keys")',
  check: 'composer discord: a chord change in the last bar of each loop; composer cluster: the turnaround bar forms its own small cluster.',
  anti: ['Turnarounds on every bar'], tags: ['transition', 'harmony'], tool: 'cluster', needs: 'hooks' });

// ------------------------------------------------------------------ groove and feel
add('grv', 'GRV-01', 'Rhythm sequence archetypes', { def: 'Named drum skeletons: four-on-the-floor (house, big room), two-step (DnB), half-time (dubstep, trap, phonk), boom-bap, tresillo 3+3+2, electro broken kick, hyphy bounce.',
  why: 'Each archetype sets the metric hierarchy listeners dance to; genre recognition starts from it.',
  when: 'Pick one per section; a beat switch changes it (ARR-04).',
  code: '$: s("bd*4, ~ cp ~ cp, [~ hh]*4").hook("hygiene-kick")  // four-floor\n$: s("bd ~ ~ ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~, ~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~ ~ ~").hook("hygiene-kick").mask("<0 1>")  // two-step',
  check: 'composer scan / feel: modal onset pattern, half-time flag, syncopation index.',
  anti: ['Mixing two archetypes in one section by accident (ambiguous downbeat)'], tags: ['four-floor', 'half-time', 'drums'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-02', 'Swing', { def: 'The second 16th (or 8th) of each pair delayed: 50 % straight, 54-58 % pocket, 66.7 % triplet (pat.groove swing).',
  why: 'Long-short pairs create lilt; small swing values are felt rather than heard.',
  when: 'Hip-hop, house hats, boom-bap; little or none in big room and riddim.',
  code: '$: s("hh*16").hook("hygiene-hat").groove({ swing: 57, seed: 1 }).gain(0.4)\n$: s("bd ~ ~ bd ~ ~ bd ~, ~ sd").hook("hygiene-kick")',
  check: 'composer feel / scan: swing16 within 1-2 % of the target.',
  anti: ['Two swings stacked (pat.groove and swingBy) (they compose)', 'Swinging the kick and not the hats (flam feel)'], tags: ['swing', 'human-feel'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-03', 'Push and pull', { def: 'A constant early (push, rush) or late (pull, drag) offset per voice, in % of a 16th.',
  why: 'Relative timing between voices sets feel: late snares feel laid back, early hats urgent.',
  when: 'Lazy / cloud feels (snare + 5-10 %), bouncy feels (hats - 3 %).',
  code: '$: s("~ sd").hook("hygiene-snare").groove({ push: 8, seed: 2 })\n$: s("bd ~ ~ bd").hook("hygiene-kick")',
  check: 'composer feel / scan: push_high_vs_low_pct16.',
  anti: ['Pushing the whole mix (nothing changes relatively)'], tags: ['human-feel', 'swing'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-04', 'Micro-timing (humanize)', { def: 'Small per-hit timing spread (jitter 1-5 % of a 16th) and slow drift, seeded and deterministic.',
  why: 'Players deviate 5-20 ms; a little variance reads as alive, too much as sloppy.',
  when: 'Hats, percussion, keys; not the kick in four-floor genres.',
  code: '$: s("hh*16").hook("hygiene-hat").groove({ jitter: 3, vel: 0.12, drift: 1, seed: 3 }).gain(0.4)',
  check: 'composer feel / scan: jitter_pct16 within the feel template range.',
  anti: ['Random jitter on the kick and sub (phase smear)'], tags: ['human-feel'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-05', 'Ghost notes', { def: 'Quiet notes (velocity 0.1-0.35) between the main hits, mostly snare and hats.',
  why: 'Ghosts fill the subdivision grid at low salience: the groove gets motion without changing its accents.',
  when: 'Boom-bap, DnB breaks, funk-derived house, phonk.',
  code: '$: s("~ sd ~ sd").hook("hygiene-snare")\n$: s("~ ~ ~ sd ~ ~ sd ~ ~ sd ~ ~ ~ ~ ~ sd").hook("hygiene-snare").velocity(0.22)',
  check: 'composer feel / scan: ghost_share and ghosts_per_bar.',
  anti: ['Ghosts as loud as accents (they stop being ghosts)'], tags: ['accents', 'drums'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-06', 'Polymeter and hemiola', { def: 'A cycle of 3 (or 6) against the 4 of the bar: a 3-step riff over 16ths, 3+3+2 groupings.',
  why: 'Phase drift between cycles creates moving accents over a stable pulse (realigns every LCM steps).',
  when: 'Techno, DnB riffs, trap hats, builds.',
  code: '$: note("c3 eb3 g3").fast(16/3).s("triangle").hook("hygiene-arp").gain(0.4)\n$: s("bd*4").hook("hygiene-kick")',
  check: 'composer scan / feel: hemiola_hint (autocorrelation at lag 3 or 6 beats lag 4 and 8).',
  anti: ['Polymeter on the kick in a dance track (the floor loses the pulse)'], tags: ['polyrhythm', 'syncopated'], tool: 'feel', needs: 'hooks' });
add('grv', 'GRV-07', 'Picking a feel', { def: 'Choose a feel template (feel-boombap, lazy, trap, hyphy, cloud, halftime, ukf, riddim, brostep) from measured or intended stats.',
  why: 'A feel is a coherent set of tempo, archetype and groove settings; picking one keeps all voices consistent.',
  when: 'At the start, or from a reference you own: composer scan, then composer feel.',
  code: 'setcpm(140/4)\natoms.import("pack:glyphcore/phonk:feel-trap", { as: "feel" })\nhooks.bind("kick", atoms.feel.kickRack)\n$: s(atoms.feel.kick).velocity(atoms.feel.kickVel).use("kick")',
  check: 'composer feel: ranked feels with distances; the measured .groove line.',
  anti: ['Copying a reference track\'s pattern (measure feel stats, never transcribe or duplicate)'], tags: ['feel', 'groove'], tool: 'feel', needs: 'hooks' });

// ------------------------------------------------------------------ harmony
add('har', 'HAR-01', 'Voice leading', { def: 'Chord changes with the smallest moves per voice; common tones held.',
  why: 'Small moves keep voices as continuous streams; pads sound smooth instead of jumping.',
  when: 'Pads, supersaw chords, keys.',
  code: '$: chord("<Cm7 Abmaj7 Ebmaj7 Bb7>").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'engine/motifs chord loop; pitch moves per voice <= 2 semitones (voicing()).',
  anti: ['Root-position block chords jumping a fifth each change'], tags: ['harmony', 'pad'], tool: 'discord', needs: 'hooks' });
add('har', 'HAR-02', 'Bass-note pedal', { def: 'The bass holds one note while chords change above (I - IV/I - bVII/I).',
  why: 'Inverted and slash chords over a pedal give tension and colour with a stable floor.',
  when: 'Intros, builds, phonk and techno drones.',
  code: '$: note("c2*4").s("sawtooth").hook("hygiene-bass")\n$: chord("<Cm Fm Bb Cm>").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord: one bar root across chord changes; roughness changes per chord.',
  anti: ['A pedal through a whole track with no release'], tags: ['harmony', 'drone'], tool: 'discord', needs: 'hooks' });
add('har', 'HAR-03', 'Harmonic rhythm', { def: 'How often chords change: 1 per 2 bars (house, dubstep), 1 per bar (pop), 2 per bar (turnarounds).',
  why: 'Faster harmonic rhythm raises energy and forward motion; slower lets texture and groove lead.',
  when: 'Accelerate into a drop or chorus, slow down in breakdowns.',
  code: '$: chord("<Cm Ab Eb Bb>/2").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord / engine/motifs: chord changes per bar per section.',
  anti: ['Changing harmonic rhythm under a vocal phrase mid-line'], tags: ['harmony'], tool: 'discord', needs: 'hooks' });
add('har', 'HAR-04', 'Modal colour per genre', { def: 'Pick the mode for its colour: Aeolian (most EDM), Dorian (house, liquid), Phrygian (phonk, darker dubstep), harmonic minor (Italo, trance tension).',
  why: 'The characteristic degree (natural 6 in Dorian, b2 in Phrygian) carries the mood.',
  when: 'At the brief; borrowing (BOR) can mix modes per section.',
  code: '$: n("0 1 3 4 1 0").scale("C4:phrygian").s("square").hook("hygiene-bell").gain(0.4)',
  check: 'composer discord: borrowing names b2 (Phrygian) or natural 6 (Dorian) against the minor key.',
  anti: ['Phrygian b2 against a held natural 2 (unwanted clash)'], tags: ['harmony', 'dark'], tool: 'discord', needs: 'hooks' });

// ------------------------------------------------------------------ tone borrowing
add('bor', 'BOR-01', 'Modal interchange (borrowed chords)', { def: 'A chord from the parallel mode inside the key: iv, bVI, bVII in major; IV, major V in minor.',
  why: 'One altered degree (b6, b7, or a raised 6 / 7) changes colour without leaving the tonic (music theory: mode mixture).',
  when: 'Sentimental lifts, pre-choruses, last chords before a drop.',
  code: '$: chord("<C F Fm C>").voicing().s("triangle").hook("hygiene-keys")',
  check: 'composer discord: borrowing lists b6 (mixture, bVI / iv) in that section.',
  anti: ['Borrowing every bar (the key stops being clear)'], tags: ['borrowing', 'harmony'], tool: 'discord', needs: 'hooks' });
add('bor', 'BOR-02', 'Parallel and relative shifts', { def: 'A section in the parallel major/minor (C minor -> C major) or the relative key (C minor -> Eb major).',
  why: 'Same tonic, opposite mode (parallel) or same notes, new centre (relative): big mood change with continuity.',
  when: 'Breakdowns, bridges, the final drop.',
  code: '$: n("0 2 4 3").scale("<C4:minor C4:major>").s("triangle").hook("hygiene-lead")',
  check: 'composer discord: key_shift on the section (or major 3 "parallel major" named).',
  anti: ['Shifting mode under a sustained vocal note that clashes'], tags: ['borrowing'], tool: 'discord', needs: 'hooks' });
add('bor', 'BOR-03', 'Picardy third', { def: 'A minor piece ends on a major tonic chord.',
  why: 'The raised third surprises at the cadence and reads as release or hope.',
  when: 'Outros, the last chord of a breakdown.',
  code: '$: chord("<Cm Fm G C>").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord: "major 3 (Picardy / parallel major)" in the last section.',
  anti: ['Using it on every loop (it becomes the key)'], tags: ['borrowing', 'bright'], tool: 'discord', needs: 'hooks' });
add('bor', 'BOR-04', 'Chromatic mediants', { def: 'Chords a third apart that share at most one tone (C major -> E major, Cm -> Ab with a major-third root move and borrowed quality).',
  why: 'Large colour shift with smooth common-tone voice leading: cinematic and "lift" effect.',
  when: 'Section seams, trailer-like moments, melodic dubstep breakdowns.',
  code: '$: chord("<Cm E Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord: chromatic_mediants list.',
  anti: ['Mediant shifts under a modal vocal melody'], tags: ['borrowing', 'harmony'], tool: 'discord', needs: 'hooks' });
add('bor', 'BOR-05', 'Key-shift lift', { def: 'The last chorus or drop moves up (often 1 or 2 semitones; a fourth or fifth for a broader lift).',
  why: 'Raised pitch raises brightness and arousal; the familiar hook in a new key feels like a lift.',
  when: 'The final hook; once per track.',
  code: '$: n("0 2 4 3").scale("<C4:minor C4:minor D4:minor D4:minor>").s("sawtooth").hook("hygiene-lead")',
  check: 'composer discord: key_shift with lift_semitones in the last drop; composer ledger: "transposed" statements there.',
  anti: ['A lift without preparation (pivot chord or gap)'], tags: ['borrowing', 'build-drop'], tool: 'discord', needs: 'hooks' });
add('bor', 'BOR-06', 'Timbre borrowing', { def: 'Take the timbre of one layer for another: neuro growl formants on a pad, a vocal formant on the bass, bell FM on a pluck.',
  why: 'Shared spectral envelope across layers binds them (ASN) and makes a new colour from known material.',
  when: 'Drops of bass genres; breakdowns that reuse the drop\'s colour softly.',
  code: '$: note("c2*4").s("sawtooth").hook("hygiene-bass").vowel("o")\n$: chord("<Cm Ab>").voicing().s("sawtooth").hook("hygiene-pad").vowel("o").gain(0.2)',
  check: 'composer layers: shared vowel or high MFCC cosine (stems) between the two layers.',
  anti: ['Borrowing a timbre into the same band (masking instead of binding)'], tags: ['borrowing', 'formant'], tool: 'layers', needs: 'hooks' });
add('bor', 'BOR-07', 'Groove and envelope borrowing', { def: 'One layer takes another layer\'s rhythm or envelope (the hat rhythm on a pluck, the kick envelope on a pad via sidechain), or a genre feel on a new style.',
  why: 'Shared onsets and envelopes lock layers into one groove (common fate).',
  when: 'Drops; genre blends (hyphy feel under a house chord).',
  code: 'atom("hats", { type: "mini", body: "~ x ~ x ~ x ~ x" })\n$: s("hh").struct(atoms.hats).hook("hygiene-hat").gain(0.4)\n$: n("0 2 4 2").scale("C5:minor").struct(atoms.hats).s("triangle").hook("hygiene-pluck")',
  check: 'composer layers: rhythm_rhyme / envelope_rhyme high for the pair.',
  anti: ['Borrowing a groove that fights the main archetype'], tags: ['borrowing', 'groove'], tool: 'layers', needs: 'hooks' });
add('bor', 'BOR-08', 'Harmonic skeleton borrowing', { def: 'A section reuses another section\'s chord loop or bass skeleton with new material on top.',
  why: 'Continuity of harmony makes contrasting melodies belong to one piece.',
  when: 'Breakdowns over the drop loop; verses over the hook chords.',
  code: 'atom("loop", { type: "mini", body: "<Cm Ab Eb Bb>" })\n$: chord(atoms.loop).voicing().s("supersaw").hook("hygiene-pad").gain(0.2).mask("<1 1 0 0>")\n$: chord(atoms.loop).voicing().s("triangle").hook("hygiene-keys").struct("x ~ x x").mask("<0 0 1 1>")',
  check: 'composer foreshadow: planted_harmony; composer discord: same roots per bar in both sections.',
  anti: ['Different loops in every section (no harmonic identity)'], tags: ['borrowing', 'harmony'], tool: 'foreshadow', needs: 'hooks' });

// ------------------------------------------------------------------ discordance
add('dis', 'DIS-01', 'Minor-second and tritone stabs', { def: 'Short stabs whose voicing contains a minor 2nd, major 7th or tritone.',
  why: 'Partials within a critical band beat and roughen (Plomp-Levelt); short duration keeps the roughness a hit, not a texture.',
  when: 'Dark drops, industrial dubstep, phonk bells (the cowbell\'s near-tritone partials), horror tints.',
  code: '$: note("<[c4,gb4] [c4,db4]>").s("square").hook("hygiene-stab").decay(0.12).sustain(0).struct("x ~ ~ x ~ ~ x ~")',
  check: 'composer discord: interval classes m2/M7, tritone in the section; roughness peaks on the stabs.',
  anti: ['Sustained clashes under a vocal (unintended "out of tune")'], tags: ['discordance', 'dark', 'stab'], tool: 'discord', needs: 'hooks' });
add('dis', 'DIS-02', 'Cluster stabs', { def: 'Three or more adjacent scale tones at once (c-d-eb), short.',
  why: 'Maximum roughness per event; reads as a percussive, metallic hit.',
  when: 'Impacts, industrial textures, builds.',
  code: '$: note("[c4,d4,eb4]").s("sawtooth").hook("hygiene-stab").decay(0.1).sustain(0).struct("<x ~ ~ ~>")',
  check: 'composer discord: interval class "cluster"; roughness x2+ the section median on the hit bars.',
  anti: ['Low clusters (below ~200 Hz: mud, not bite)'], tags: ['discordance', 'clustering'], tool: 'discord', needs: 'hooks' });
add('dis', 'DIS-03', 'Detuned unison beating', { def: 'Two or more copies of a voice detuned by a few cents (supersaw, reese).',
  why: 'Beating at the frequency difference gives motion and width; at low pitch it becomes audible pulsing.',
  when: 'Reese basses (DnB, neuro), supersaw chords; keep the sub itself clean.',
  code: '$: note("c2").s("supersaw").unison(2).detune(0.3).hook("hygiene-reese").lpf(1200).struct("x@3 ~")',
  check: 'composer discord: roughness counts detuned copies (unison, detune); composer layers stems: the sub stem stays clean (no beating under 60 Hz).',
  anti: ['Detuning the sub (phase cancellation, mono collapse)'], tags: ['discordance', 'bass', 'reese'], tool: 'discord', needs: 'hooks' });
add('dis', 'DIS-04', 'Bitonal layers', { def: 'Two layers in keys a tritone or semitone apart for a short span.',
  why: 'Two tonal centres compete; the ear cannot settle: strong unease, best brief.',
  when: 'Horror tints, the last bars of an industrial build.',
  code: '$: n("0 2 4").scale("C4:minor").s("triangle").hook("hygiene-pluck")\n$: n("0 2 4").scale("F#3:minor").s("sawtooth").hook("hygiene-lead").gain(0.3).mask("<0 0 0 1>")',
  check: 'composer discord: per-section key fit drops; out-of-key share rises in that section only.',
  anti: ['Bitonality for whole sections without intent'], tags: ['discordance', 'tense'], tool: 'discord', needs: 'hooks' });
add('dis', 'DIS-05', 'Dissonance-to-resolution timing', { def: 'Place the clash on a weak or pre-arrival position and resolve on the downbeat (appoggiatura logic).',
  why: 'Tension then release; an unresolved clash reads as error, a resolved one as intent.',
  when: 'Pre-drop bars, phrase ends.',
  code: '$: chord("<[c4,db4,g4] [c4,eb4,g4]>").s("supersaw").hook("hygiene-pad").gain(0.25)',
  check: 'composer discord: every clash has resolved_at within 2 bars; unresolved list empty (or intended).',
  anti: ['Clashes left hanging at section ends'], tags: ['discordance', 'tension'], tool: 'discord', needs: 'hooks' });
add('dis', 'DIS-06', 'Roughness as sound design', { def: 'Distortion, FM and ring-style sidebands that create inharmonic, rough spectra (wet industrial, growls).',
  why: 'Inharmonic partials close together raise sensory roughness; it reads as aggression and grit.',
  when: 'Growl and riddim basses, industrial dubstep, phonk distortion; keep the sub separate.',
  code: '$: note("c2 ~ c2 ~").s("sawtooth").hook("hygiene-growl").fm(3).fmh(1.41).distort(2).lpf(2000)\n$: note("c1 ~ c1 ~").s("sine").hook("hygiene-sub")',
  check: 'composer discord --audio on the stem: roughness per bar; composer scan band map: grit above 200 Hz, a clean sub band.',
  anti: ['Distorting the sub with the growl (one band split first, SND-02)'], tags: ['discordance', 'growl', 'fm'], tool: 'discord', needs: 'hooks' });

// ------------------------------------------------------------------ assonance
add('asn', 'ASN-01', 'Shared vowel formants', { def: 'Two layers filtered to the same vowel (bass and vocal syllables both on "o").',
  why: 'Formants are the strongest cue for sound similarity in voice-like sounds; shared formants bind layers into one colour.',
  when: 'Talking basses with vocal chops, formant pads with leads.',
  code: '$: note("c2*4").s("sawtooth").hook("hygiene-bass").vowel("<o a>")\n$: n("0 2 4 3").scale("C4:minor").s("sawtooth").vowel("<o a>").hook("hygiene-vox").gain(0.4)',
  check: 'composer layers: colour "shared vowel" for the pair; stems: high MFCC cosine.',
  anti: ['Same vowel and same band (masking)'], tags: ['assonance', 'formant'], tool: 'layers', needs: 'hooks' });
add('asn', 'ASN-02', 'Shared harmonic series', { def: 'Layers placed on partials of one fundamental (octaves, fifths over the bass root).',
  why: 'Harmonic partials fuse (harmonicity): the layers sound like one rich tone.',
  when: 'Pads over a sub, drones, bell layers.',
  code: '$: note("c1").s("sine").hook("hygiene-sub")\n$: note("[c3,g3,c4,e4]").s("triangle").hook("hygiene-pad").gain(0.2)',
  check: 'composer discord: low roughness with many voices; composer layers stems: lufs_gain_db >= 0 (no cancellation).',
  anti: ['Tempered thirds high above a sub expecting perfect fusion (slight beating is normal)'], tags: ['assonance', 'consonance'], tool: 'discord', needs: 'hooks' });
add('asn', 'ASN-03', 'Repeated colour and noise texture', { def: 'One noise colour (vinyl, tape hiss, pink air) or one reverb space shared by several layers.',
  why: 'A common acoustic signature (same room, same noise floor) makes separate sources sound recorded together.',
  when: 'Lo-fi, phonk, cloud; any mix that feels disjointed.',
  code: '$: s("bd ~ sd ~").hook("hygiene-kick").room(0.3).size(2)\n$: n("0 2 4 3").scale("C4:minor").s("triangle").hook("hygiene-keys").room(0.3).size(2)\n$: s("pink").hpf(4000).gain(0.03)',
  check: 'composer layers: same room / filter colour; composer scan: a constant noise floor in the brilliance band.',
  anti: ['Noise so loud it masks transients'], tags: ['assonance', 'texture'], tool: 'layers', needs: 'hooks' });
add('asn', 'ASN-04', 'Rhyming rhythm cells', { def: 'Two layers share a rhythm cell (same onsets) with different pitches or sounds.',
  why: 'Shared onsets group layers by common fate; the groove gets one identity.',
  when: 'Drops: bass and stab, kick and sub, chord stabs and hats.',
  code: 'atom("cell", { type: "mini", body: "x ~ x ~ ~ x ~ x" })\n$: note("c2").struct(atoms.cell).s("sawtooth").hook("hygiene-bass")\n$: chord("Cm").voicing().struct(atoms.cell).s("square").hook("hygiene-stab").decay(0.1).sustain(0)',
  check: 'composer layers: rhythm_rhyme close to 1 for the pair.',
  anti: ['Every layer on the same cell (no complement left, see CMP-02)'], tags: ['assonance', 'groove'], tool: 'layers', needs: 'hooks' });
add('asn', 'ASN-05', 'Rhyming envelopes', { def: 'Layers share an attack/decay shape (all plucky, or all swelling).',
  why: 'Envelope shape is a primary timbre cue; matching envelopes make layers belong to one gesture.',
  when: 'Pluck layers, stab stacks, pad beds.',
  code: '$: note("c4 eb4 g4").s("triangle").hook("hygiene-pluck").attack(0.002).decay(0.15).sustain(0)\n$: note("c5 g5").s("square").hook("hygiene-pluck").attack(0.002).decay(0.15).sustain(0).gain(0.3)',
  check: 'composer layers: envelope_rhyme close to 1.',
  anti: ['One slow-attack layer inside a pluck stack (smears the transient)'], tags: ['assonance'], tool: 'layers', needs: 'hooks' });
add('asn', 'ASN-06', 'Onset alliteration', { def: 'Several layers start together on chosen beats (accents everyone hits), then separate.',
  why: 'Coincident onsets are heard as one accent: hits get weight; the rest of the bar stays clear.',
  when: 'Accents on 1 and the "and of 2" in hip-hop; drop downbeats.',
  code: '$: s("bd ~ ~ bd ~ ~ ~ ~").hook("hygiene-kick")\n$: note("c2 ~ ~ c2 ~ eb2 ~ ~").s("sawtooth").hook("hygiene-bass")\n$: chord("Cm").voicing().struct("x ~ ~ x ~ ~ ~ ~").s("square").hook("hygiene-stab").decay(0.1).sustain(0)',
  check: 'composer layers: onset_lock above chance for the accent layers.',
  anti: ['Everything on every accent (flams if timing differs)'], tags: ['assonance', 'accents'], tool: 'layers', needs: 'hooks' });

// ------------------------------------------------------------------ complementing
add('cmp', 'CMP-01', 'Spectral complement and mask-aware carving', { def: 'Layers that compete get mirrored filtering: where one is boosted, the other is cut (or high/low-passed apart).',
  why: 'Masking is band-local: removing overlap gives each layer its own critical bands (producer-reported "puzzle-piece" EQ).',
  when: 'Kick vs bass, vocal vs lead, pads vs keys.',
  code: '$: note("c2*8").s("sawtooth").hook("hygiene-bass").lpf(900)\n$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").hpf(500).gain(0.2)',
  check: 'composer layers (stems): masking_index falls after carving; composer density: no slot suggestions.',
  anti: ['Carving so deep a layer sounds hollow solo and in context'], tags: ['complement', 'mix'], tool: 'layers', needs: 'hooks' });
add('cmp', 'CMP-02', 'Rhythmic complement', { def: 'Onbeat vs offbeat, notes in the other layer\'s rests (the offbeat bass in house, hats between kicks).',
  why: 'Interleaved onsets give a denser composite rhythm with no masking in time.',
  when: 'Bass vs kick, chops vs snare, counterlines.',
  code: '$: s("bd*4").hook("hygiene-kick")\n$: note("~ c2 ~ c2 ~ c2 ~ c2").s("sawtooth").hook("hygiene-bass")',
  check: 'composer layers: onset_complement close to 1 and "best complement" for each layer.',
  anti: ['Complement so strict both layers sound like one choppy part'], tags: ['complement', 'offbeat'], tool: 'layers', needs: 'hooks' });
add('cmp', 'CMP-03', 'Sustained vs staccato', { def: 'Long notes against short ones: pad against plucks, held bass against stabs.',
  why: 'Different envelopes separate into streams and fill both the time and the spectrum.',
  when: 'Any two melodic layers that share a register.',
  code: '$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").gain(0.2)\n$: n("0 2 4 3 2 4 5 4").scale("C5:minor").s("triangle").hook("hygiene-pluck").decay(0.1).sustain(0)',
  check: 'composer layers: length_contrast >= 2 (log2 ratio of median durations).',
  anti: ['Two pads in one register'], tags: ['complement'], tool: 'layers', needs: 'hooks' });
add('cmp', 'CMP-04', 'Stereo complement', { def: 'Mono low end and lead; width in pads, hats, reverbs; panned pairs left/right.',
  why: 'Spatial separation releases masking (binaural unmasking) and mono lows stay solid on any system.',
  when: 'Always: bass and kick mono, supporting layers wide.',
  code: '$: note("c1*4").s("sine").hook("hygiene-sub")\n$: n("0 2 4 3").scale("C5:minor").s("triangle").hook("hygiene-pluck").pan(sine.range(0.2, 0.8))',
  check: 'composer layers: pan_contrast; stems: low-band correlation stays mono.',
  anti: ['Wide sub or wide kick'], tags: ['complement', 'stereo'], tool: 'layers', needs: 'hooks' });
add('cmp', 'CMP-05', 'Dynamic complement (ducking)', { def: 'One layer gets quieter while another plays (sidechain, ducking on a bus).',
  why: 'Time-varying gain separates layers in loudness when they must share a band.',
  when: 'Kick and sub, vocal and pads, impacts and the mix.',
  code: '$: s("bd*4").hook("hygiene-kick").duckorbit(2).duckdepth(0.6)\n$: note("c1*8").s("sine").hook("hygiene-sub").orbit(2)',
  check: 'composer density: the sub slot shared by a ducked pair is not flagged; stems: kick transients clear.',
  anti: ['Pumping everything (the groove becomes the compressor)'], tags: ['complement', 'sidechain'], tool: 'density', needs: 'hooks' });

// ------------------------------------------------------------------ synergy
add('syn', 'SYN-01', 'Kick and sub lock', { def: 'The kick\'s pitch and decay tuned with the sub: same root, the sub ducked or starting after the kick transient.',
  why: 'In phase and in tune the two sum into one low event; out of phase they cancel (comb filtering at the overlap).',
  when: 'Every genre with a separate kick and sub (trap 808 + kick, dubstep, DnB).',
  code: '$: s("bd ~ ~ bd").s("sine").hook("hygiene-kick").freq(55).decay(0.3).duckorbit(2).duckdepth(0.7)\n$: note("a0 ~ ~ a0").s("sine").hook("hygiene-sub").orbit(2)',
  check: 'composer layers (stems): lufs_gain_db >= 0 for kick + sub (no cancellation); events: onset_lock over chance.',
  anti: ['Kick and sub a semitone apart', 'No ducking and long sub tails under every kick'], tags: ['synergy', 'low-end', 'sidechain'], tool: 'layers', needs: 'hooks' });
add('syn', 'SYN-02', 'Bass and pad reinforcement', { def: 'The pad voices sit on the bass note\'s partials (octave, fifth, tenth), so together they make one chord-tone.',
  why: 'Harmonic reinforcement raises loudness of shared partials and fuses the two.',
  when: 'Breakdowns and drops with sustained chords.',
  code: '$: note("<c2 ab1>").s("sawtooth").hook("hygiene-bass").lpf(500)\n$: chord("<C5 Ab5>").voicing().s("supersaw").hook("hygiene-pad").gain(0.2)',
  check: 'composer layers (stems): lufs_gain_db > 0.5 ("reinforce").',
  anti: ['Pad thirds in the bass octave'], tags: ['synergy', 'pad'], tool: 'layers', needs: 'hooks' });
add('syn', 'SYN-03', 'Snare and noise tail', { def: 'A tonal snare body and a noise layer that only work together (body + tail).',
  why: 'Transient, body and decay come from different layers; each alone is thin, together they make one snare.',
  when: 'Snares and claps in every genre.',
  code: '$: s("~ sd").s("triangle").note("d3").hook("hygiene-snare").decay(0.12).sustain(0)\n$: s("~ x").s("white").hpf(2000).decay(0.18).sustain(0).gain(0.5)',
  check: 'composer layers: onset_lock 1.0 for the pair, different bands.',
  anti: ['Layers with different onsets (flam)'], tags: ['synergy', 'drums'], tool: 'layers', needs: 'hooks' });
add('syn', 'SYN-04', 'Vocal formant and lead filter sweep', { def: 'The lead\'s filter sweeps through the same region as the vocal\'s formants, alternating in time.',
  why: 'Shared spectral region in alternation reads as a duet of one colour.',
  when: 'Hooks with vocal chops and a synth lead.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").hook("hygiene-lead").lpf(sine.slow(2).range(700, 1400)).mask("<1 0>")\n$: n("0 2 4 3").scale("C4:minor").s("sawtooth").vowel("a").hook("hygiene-vox").mask("<0 1>")',
  check: 'composer layers: filter centres within 1/2 octave and onset_complement high.',
  anti: ['Sweeping through the vocal while it sings'], tags: ['synergy', 'formant'], tool: 'layers', needs: 'hooks' });
add('syn', 'SYN-05', 'Sidechain interplay', { def: 'The kick ducks pads and bass so the pumping becomes part of the groove.',
  why: 'Amplitude modulation at the beat rate synchronises layers to the kick (common fate).',
  when: 'House, big room, French house filter loops, phonk drops.',
  code: '$: s("bd*4").hook("hygiene-kick").duckorbit(3).duckdepth(0.6)\n$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").orbit(3).gain(0.3)',
  check: 'composer scan: low-band onset pattern on every beat and pad energy dips between; composer density ducks recognised.',
  anti: ['Masking sidechain because it is "EDM": it is a tool for any genre (user directive)'], tags: ['synergy', 'sidechain'], tool: 'scan', needs: 'hooks' });

// ------------------------------------------------------------------ clustering
add('clu', 'CLU-01', 'Tone clusters', { def: 'Adjacent tones sounded together (seconds), as colour (soft, high) or as attack (loud, short).',
  why: 'High soft clusters shimmer (beating as texture); loud clusters are percussive roughness.',
  when: 'Ambient pads (high, quiet), impacts (loud, short).',
  code: '$: note("[c5,d5,eb5,f5]").s("triangle").hook("hygiene-pad").attack(1).release(2).gain(0.1)',
  check: 'composer discord: "cluster" interval class; roughness level vs section median.',
  anti: ['Mid-low clusters held under a vocal'], tags: ['clustering', 'pad'], tool: 'discord', needs: 'hooks' });
add('clu', 'CLU-02', 'Chord clusters (dense voicings)', { def: 'Add9, sus2, 6/9 and 11 voicings with seconds inside, spread above 200 Hz.',
  why: 'Seconds inside open voicings add colour (the "bittersweet" melodic-bass sound) without the roughness of close low clusters.',
  when: 'Melodic dubstep and future bass chords, liquid DnB pads.',
  code: '$: chord("<Cm9 Abmaj9 Eb6 Bbsus2>").voicing().s("supersaw").hook("hygiene-supersaw").gain(0.2)',
  check: 'composer discord: m2/M7 present with moderate roughness (no clash flag).',
  anti: ['Clustered voicings below 200 Hz'], tags: ['clustering', 'harmony'], tool: 'discord', needs: 'hooks' });
add('clu', 'CLU-03', 'Rhythmic clusters', { def: 'Bursts of events in a short span: flams, ratchets, drags, rolls.',
  why: 'A burst is heard as one ornamented event: emphasis and swing within a beat.',
  when: 'Trap hats, DnB snares, fills.',
  code: '$: s("hh*8").hook("hygiene-hat").ply("<1 1 2 [1 3]>").gain(0.4)\n$: s("~ sd ~ [sd sd]").hook("hygiene-snare")',
  check: 'composer feel: ghost and onset counts per bar; rhythm cells with subdivisions in the ledger rhythm list.',
  anti: ['Ratchets on every beat (machine-gun)'], tags: ['clustering', 'drums', 'trap'], tool: 'feel', needs: 'hooks' });
add('clu', 'CLU-04', 'Event clustering over time', { def: 'Density bursts at points: more events just before the drop, sparse elsewhere.',
  why: 'Time-varying density shapes expectation; bursts point at arrivals.',
  when: 'The last 1-2 bars of builds, the bar before a switch.',
  code: '$: s("sd").hook("hygiene-snare").fast("<1 1 2 8>")\n$: s("hh*8").hook("hygiene-hat").gain(0.3).mask("<1 1 1 0>")',
  check: 'composer density: onsets per bar peak at the end of the build.',
  anti: ['Uniform density (no burst, no arrival)'], tags: ['clustering', 'build-drop'], tool: 'density', needs: 'hooks' });
add('clu', 'CLU-05', 'Bar clustering (analysis)', { def: 'k-means over per-bar features (band energies, centroid, flatness, onsets or lane activation) finds section types without a form.',
  why: 'Bars that sound alike cluster together; the run lengths reveal the form, turnaround bars and transition bars.',
  when: 'Audio you own (find its form), or a draft (did the drop really change?).',
  code: '// engine/composer/run.sh cluster MIX.wav OUT --bpm 128 [--form form.json]\n$: s("bd*4, hh*8").hook("hygiene-kick").mask("<1 1 0 0 1 1>")',
  check: 'composer cluster: labels, runs, adjusted Rand index against the form.',
  anti: ['Reading clusters as genre rules: they describe one track'], tags: ['clustering', 'analysis'], tool: 'cluster', needs: 'hooks' });
add('clu', 'CLU-06', 'Motif clustering by contour', { def: 'Group motif cells by their up/down contour to find families of related ideas.',
  why: 'Contour is the most robust identity cue; cells sharing it sound related even with different intervals.',
  when: 'After drafting: are the motifs one family (unity) or unrelated (patchwork)?',
  code: '// engine/composer/run.sh ledger PROGRAM.strudel.js OUT -> contour_families\n$: n("<[0 2 4 3] [0 3 5 4]>").scale("C4:minor").s("triangle").hook("hygiene-pluck")',
  check: 'composer ledger: contour_families.',
  anti: ['Too many unrelated contours in one track'], tags: ['clustering', 'motif', 'analysis'], tool: 'ledger', needs: 'hooks' });
add('clu', 'CLU-07', 'Timbral clustering', { def: 'Group sounds into a few timbral families (metallic, airy, woody, distorted) and assign families to sections.',
  why: 'A limited palette per section reads as intent; switching families marks sections.',
  when: 'Planning the palette; checking stems.',
  code: '$: n("0 2 4").scale("C5:minor").s("square").hook("hygiene-bell").fm(2.01).decay(0.4).sustain(0).mask("<1 0>")\n$: n("0 2 4").scale("C4:minor").s("triangle").hook("hygiene-pluck").mask("<0 1>")',
  check: 'composer layers (stems): MFCC cosine groups; composer cluster on stems.',
  anti: ['Every layer a different family (no palette)'], tags: ['clustering', 'texture'], tool: 'layers', needs: 'hooks' });

// ------------------------------------------------------------------ sound-design layering
add('snd', 'SND-01', 'Sub, body, bite, air', { def: 'One instrument from four layers: sub (sine, mono, < 100 Hz), body (100-500 Hz), bite (1-5 kHz transient or grit), air (> 8 kHz noise).',
  why: 'Each band carries a different cue (weight, warmth, presence, sheen); separate layers allow separate processing and mono / stereo choices.',
  when: 'Basses, leads and snares that must translate on small and large systems.',
  code: '$: note("c1*2").s("sine").hook("hygiene-sub")\n$: note("c2*2").s("sawtooth").hook("hygiene-bass").hpf(100).lpf(500)\n$: note("c3*2").s("square").hook("hygiene-growl").hpf(1000).distort(1.5).gain(0.3)\n$: s("white*2").hpf(8000).decay(0.05).sustain(0).gain(0.1)',
  check: 'composer scan band map: one layer dominant per band; composer layers stems: low masking between the layers.',
  anti: ['Every layer full range (phase mush in the lows)'], tags: ['sound-design', 'layering'], tool: 'scan', needs: 'hooks' });
add('snd', 'SND-02', 'Parallel processing and band split', { def: 'Process a copy in parallel (distortion, compression) or split by band (.split) so the sub stays clean.',
  why: 'The low band keeps its phase and weight; the high band can be wrecked for character.',
  when: 'Growls, reeses, drums buses.',
  code: '// lo: the sub band stays clean and mono; hi: grit only above 120 Hz\nbass: note("c2*4").s("sawtooth").hook("hygiene-bass").lpf(2400)\n  .split(lo => lo.lpf(120), hi => hi.hpf(120).distort(2.5).postgain(0.45).lpf(8000))',
  check: 'composer scan: sub band stays tonal (clean) while upper bands show grit; composer discord audio roughness above 200 Hz only.',
  anti: ['Distorting the full band and then EQ-ing the sub back'], tags: ['sound-design', 'buses'], tool: 'scan', needs: 'lanes' });
add('snd', 'SND-03', 'Serial chain order', { def: 'The order of processes decides the sound: filter then distort (rounded grit) vs distort then filter (tamed harmonics).',
  why: 'Non-linear stages generate harmonics from what reaches them; order sets which partials exist.',
  when: 'Rack design (docs/RACK_STANDARD.md).',
  code: '$: note("c2*4").s("sawtooth").hook("hygiene-growl").lpf(800).distort(2)\n$: note("c2*4").s("sawtooth").hook("hygiene-growl").distort(2).lpf(800).mask("<0 1>")',
  check: 'composer scan: the two orders give different band maps (A/B in one render).',
  anti: ['Stacking reverbs before distortion (mud)'], tags: ['sound-design'], tool: 'scan', needs: 'hooks' });
add('snd', 'SND-04', 'Resampling and freezing', { def: 'Render a processed sound to audio (capture), then rework it as a sample: chop, pitch, process again.',
  why: 'Freezing modulation into a sample makes it consistent per note and opens new processing (producer-reported central in neurofunk).',
  when: 'Bass design sessions; neuro, riddim.',
  code: '// strudel capture IN --name growl -o growl.wav (docs/CAPTURE.md), then use the capture as a sample\n$: note("c2*4").s("sawtooth").hook("hygiene-growl").fm(2).distort(2)',
  check: 'the capture exists (CAPTURE.md); composer layers stems on the resampled layer.',
  anti: ['Resampling forever without committing a palette'], tags: ['sound-design', 'capture'], tool: 'layers', needs: 'core' });

// ------------------------------------------------------------------ vocal as instrument
add('vox', 'VOX-01', 'Pitched syllables and vowels', { def: 'Vowels or syllables as notes, no words: a melodic instrument with a voice colour.',
  why: 'Voice-like spectra (formants) draw attention; without words they stay instrumental.',
  when: 'Hooks, breakdowns, phonk and melodic bass chops. Never add words the user did not write.',
  code: '$: n("0 2 4 3").scale("C4:minor").s("sawtooth").vowel("<a e o a>").hook("hygiene-vox").lpf(3500)',
  check: 'composer ledger: the motif on the vox lane; composer layers: shared vowel with another layer.',
  anti: ['Inferring lyrics, crowd or choir parts the user did not ask for'], tags: ['vox', 'formant'], tool: 'ledger', needs: 'hooks' });
add('vox', 'VOX-02', 'Sustained formant pad', { def: 'A long vowel (formant filter or sustained sung vowel) as a pad layer.',
  why: 'A vowel pad is warm and human and sits in the vocal band only lightly when filtered.',
  when: 'Intros, reliefs, under sparse drops.',
  code: '$: chord("<Cm Ab>").voicing().s("sawtooth").vowel("o").hook("hygiene-pad").attack(0.8).release(2).gain(0.15)',
  check: 'composer density: atmos role; composer layers: complement with the lead (length contrast).',
  anti: ['A loud vowel pad under a lead vocal (masking in 300 Hz-3 kHz)'], tags: ['vox', 'pad', 'formant'], tool: 'density', needs: 'hooks' });
add('vox', 'VOX-03', 'Woven chops', { def: 'Short vocal slices placed in the gaps of the groove (offbeats, after the snare), pitched to the chords.',
  why: 'Short, pitched chops act as rhythmic ear candy and a call-and-response voice.',
  when: 'Drops of melodic bass, house, phonk; the user\'s own or licensed vocals only.',
  code: '$: n("<4 3> ~ 2 ~").scale("C4:minor").s("sawtooth").vowel("<e o>").hook("hygiene-vox").decay(0.12).sustain(0).late(0.125)',
  check: 'composer layers: onset_complement with the snare lane high.',
  anti: ['Chopping vocals from other artists\' tracks (never rip; the user\'s own or licensed material only)'], tags: ['vox', 'call-response'], tool: 'layers', needs: 'hooks' });

// ------------------------------------------------------------------ arrangement maps
add('arr', 'ARR-01', 'Forms as gates', { def: 'One form map as gate atoms (intro, build, drop ...); lanes are selected by gate, never copied per section.',
  why: 'One source of truth for the arrangement: changing a section length moves every layer.',
  when: 'Every full track (docs/CONVENTIONS.md section 3).',
  code: 'atom("intro", { type: "gate", body: "<3b" })\natom("drop", { type: "gate", body: "@3b" })\nkick: s("bd*4").hook("hygiene-kick").tags("drums")\npad: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").gain(0.2).tags("pad")\ntagged("drums").mute(atoms.intro)',
  check: 'composer density / cluster with --form: the gates match the cluster runs.',
  anti: ['Copy-pasted patterns per section (edits drift)'], tags: ['form', 'gate'], tool: 'cluster', needs: 'lanes' });
add('arr', 'ARR-02', 'Genre section maps', { def: 'Typical bar maps: house intro 16-32, breakdown 16-32, drop 32; DnB DJ intro 32, drop 32-48 (16 main, 16 variation, roll-out); dubstep intro 16-32, build 8, drop 16-32, switch-up second drop; trap hook 8 / verse 16; big room build 16 with 8-bar riser, drop 32.',
  why: 'Producer-reported conventions (COMPOSITION_RESEARCH.md); DJ mixing needs predictable phrase lengths in 8s.',
  when: 'Planning the form; a brief may override.',
  code: '// 18 bars at 1 cycle per bar: intro 4, build 2, drop 4, break 2, build 2, drop 4 (scale x8 for a real 144-bar map)\natom("drops", { type: "mini", body: "<0!6 1!4 0!4 1!4>" })\natom("builds", { type: "mini", body: "<0!4 1!2 0!6 1!2 0!4>" })\n$: s("bd*4").hook("hygiene-kick").mask(atoms.drops)\n$: s("sd*8").hook("hygiene-snare").gain(0.4).mask(atoms.builds)',
  check: 'composer cluster: run lengths in multiples of 8; composer density per section.',
  anti: ['Odd phrase lengths in a DJ tool without intent'], tags: ['form', 'arrangement'], tool: 'cluster', needs: 'hooks' });
add('arr', 'ARR-03', 'DJ-friendly intro and outro', { def: 'Drums-led 16-32 bar intro and outro with no full harmony, so DJs can mix.',
  why: 'Beat-matched mixing needs a rhythm-only overlap; harmonic clashes between two tracks are avoided.',
  when: 'Club tracks (house, DnB, techno); not for listening edits.',
  code: '$: s("bd*4, [~ hh]*4").hook("hygiene-kick")\n$: chord("<Cm Ab>").voicing().s("supersaw").hook("hygiene-pad").gain(0.2).mask("<0!4 1!4>")',
  check: 'composer density: intro and outro layers mostly drum role; composer discord: no harmony in the first bars.',
  anti: ['Full chords from bar 1 in a club tool'], tags: ['form', 'dj'], tool: 'density', needs: 'hooks' });
add('arr', 'ARR-04', 'Switch-up second drop', { def: 'The second drop keeps the hook but changes the beat, bass pattern or sound (beat switch, half/double time).',
  why: 'Repetition with a twist: identity plus novelty, the main reward of the second drop.',
  when: 'Dubstep, DnB, trap, phonk.',
  code: 'atom("sw", { type: "gate", body: "@3b" })\nhooks.bind("bass", [["lpf", 900]], "<3b")\nhooks.bind("bass", [["lpf", 2500], ["distort", 1.5]], atoms.sw)\n$: note("c2 ~ c2 eb2").s("sawtooth").hook("hygiene-bass").use("bass")',
  check: 'composer cluster: the second drop is a different cluster from the first; composer ledger: the hook motif present in both.',
  anti: ['A second drop identical to the first', 'A switch-up that drops the hook entirely'], tags: ['form', 'build-drop', 'gate'], tool: 'cluster', needs: 'hooks' });

export const ENTRIES = E;
